#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

run_wizard() {

# Run from the repo root so .env.local and .vercel/ land in the right place.
cd "$(git rev-parse --show-toplevel)"
ENV_FILE=".env.local"
vercel() { npx --yes vercel@latest "$@"; }

# trello_get PATH calls Trello's API with the key and token from this run. The
# credentials go in a header read from stdin, so they never show up in `ps`.
trello_get() {
  printf 'Authorization: OAuth oauth_consumer_key="%s", oauth_token="%s"\n' "$TRELLO_API_KEY" "$TRELLO_TOKEN" |
    curl -fsS -H @- "https://api.trello.com/1$1"
}
# json_field FIELD prints one top-level field of the JSON on stdin.
json_field() {
  node -e 'let s="";process.stdin.on("data",d=>s+=d).on("end",()=>console.log(JSON.parse(s)[process.argv[1]]??""))' "$1"
}
# board_code URL_OR_ID prints the short code from a board URL (trello.com/b/<code>/...), or the id as given.
board_code() {
  if [[ "$1" =~ trello\.com/b/([A-Za-z0-9]+) ]]; then printf '%s' "${BASH_REMATCH[1]}"; else printf '%s' "$1"; fi
}
# ask_board KEY "Prompt" asks for a board URL, checks Trello can see it, and saves its code to KEY.
ask_board() {
  local key="$1" prompt="$2" code name
  while true; do
    ask "$key" "$prompt" || { warn "No board given."; exit 1; }
    code=$(board_code "${!key}")
    if name=$(trello_get "/boards/$code?fields=name" 2>/dev/null | json_field name) && [[ -n "$name" ]]; then
      printf '  %s✓ found%s board "%s"\n' "$GREEN" "$RESET" "$name"
      write_env "$key" "$code"
      return
    fi
    warn "Trello couldn't find that board with this token. Check the URL and that you can open the board."
  done
}

# The Trello stages: credentials, then the boards. Run on their own with: scripts/setup.sh trello
trello_stages() {
  # ── Trello A ─────────────────────────────────────────────────────────────
  stage "Trello: API key and token"
  say "Fixline talks to Trello with your own API key and a token that lets it read and write your boards."
  note "Both are saved to $ENV_FILE (git-ignored) and never committed."
  if [[ -z "$(_existing TRELLO_API_KEY || true)" ]]; then
    open_url "https://trello.com/power-ups/admin"
    step "Click 'New' to create a Power-Up: name it 'Fixline', pick your Workspace, fill in your email."
    step "Leave the iframe connector URL empty, then click 'Create'."
    step "Open the 'API key' tab, click 'Generate a new API key', then copy the API key (not the secret)."
  else
    note "You already have a key in $ENV_FILE. Press Enter to keep it."
  fi
  ask_secret TRELLO_API_KEY "Paste the Trello API key:"
  [[ -n "$TRELLO_API_KEY" ]] || { warn "A Trello API key is required."; exit 1; }
  if [[ -z "$(_existing TRELLO_TOKEN || true)" ]]; then
    open_url "https://trello.com/1/authorize?expiration=never&scope=read,write&response_type=token&name=Fixline&key=$TRELLO_API_KEY"
    step "Check it says Fixline wants read and write access, click 'Allow', then copy the token (starts ATTA)."
  else
    note "You already have a token in $ENV_FILE. Press Enter to keep it."
  fi
  ask_secret TRELLO_TOKEN "Paste the Trello token:"
  [[ -n "$TRELLO_TOKEN" ]] || { warn "A Trello token is required."; exit 1; }
  local username
  if username=$(trello_get "/members/me?fields=username" 2>/dev/null | json_field username) && [[ -n "$username" ]]; then
    printf '  %s✓ signed in%s as %s\n' "$GREEN" "$RESET" "$username"
  else
    warn "Trello rejected that key and token. Re-run the wizard and paste them again."
    exit 1
  fi
  write_env TRELLO_API_KEY "$TRELLO_API_KEY"
  write_env TRELLO_TOKEN "$TRELLO_TOKEN"
  note "The manual 'Trello Board contract' GitHub workflow uses them too:"
  set_secret TRELLO_API_KEY "$TRELLO_API_KEY"
  set_secret TRELLO_TOKEN "$TRELLO_TOKEN"
  pause

  # ── Trello B ─────────────────────────────────────────────────────────────
  stage "Trello: the Board and the test Board"
  say "Fixline needs two Trello boards:"
  step "Harbor Lane's Board, where 'npm run intake' puts Work Orders."
  step "A separate, dedicated test Board. The contract tests create and delete Work Orders on it,"
  note "  so never point it at a Board you care about."
  open_url "https://trello.com"
  step "Create a board named 'Harbor Lane Maintenance' (skip if you have one), then copy its URL from the address bar."
  ask_board TRELLO_BOARD_ID "Paste the Harbor Lane Board's URL:"
  step "Now create a second board named 'Fixline contract tests' and copy its URL."
  while true; do
    ask_board TRELLO_TEST_BOARD_ID "Paste the test Board's URL:"
    [[ "$TRELLO_TEST_BOARD_ID" != "$TRELLO_BOARD_ID" ]] && break
    warn "That's the Harbor Lane Board. The test Board must be a different, empty board."
  done
  set_secret TRELLO_TEST_BOARD_ID "$TRELLO_TEST_BOARD_ID"
  say ""
  say "Check it all works:"
  step "npm run test:trello      runs the Board contract tests against the test Board"
  step "npm run intake -- --from maya.okafor@example.com --body \"My kitchen tap is dripping\""
  note "Fixline adds a 'Work Orders' list and Urgency, Trade and Unit labels to the board the first time it writes."
  pause
}

if [[ "${1:-}" == "trello" ]]; then
  TOTAL_STAGES=2
  banner "Fixline setup: Trello"
  trello_stages
  finish
  return
fi

TOTAL_STAGES=10
banner "Fixline setup: keys, Upstash, Vercel, deploy, Trello"

# ── 1 ──────────────────────────────────────────────────────────────────────
stage "Preflight"
say "Checking the tools this wizard needs."
command -v node >/dev/null 2>&1 || { warn "node not found: install Node 20+ first."; exit 1; }
note "node $(node --version)"
if gh auth status >/dev/null 2>&1; then
  note "gh is logged in, so GitHub secrets will be set automatically"
else
  warn "gh isn't logged in, so GitHub secrets will be skipped. Run 'gh auth login' first to have them set."
fi
note "fetching the Vercel CLI through npx (first run can take a moment)..."
vercel --version >/dev/null 2>&1 || { warn "couldn't run the Vercel CLI through npx."; exit 1; }
note "vercel CLI ready"
pause

# ── 2 ──────────────────────────────────────────────────────────────────────
stage "Groq API key (default model)"
say "Groq's free tier runs the agent locally, in CI, and on the deployed page."
if [[ -n "$(_existing GROQ_API_KEY || true)" ]]; then
  note "You already have a key in $ENV_FILE. Press Enter to keep it."
else
  open_url "https://console.groq.com/keys"
  step "Sign in, click 'Create API Key', name it 'fixline', then copy the key (starts gsk_)."
  note "Groq shows the key only once."
fi
ask_secret GROQ_API_KEY "Paste the Groq key:"
[[ -n "$GROQ_API_KEY" ]] || { warn "A Groq key is required."; exit 1; }
write_env GROQ_API_KEY "$GROQ_API_KEY"
set_secret GROQ_API_KEY "$GROQ_API_KEY"
pause

# ── 3 ──────────────────────────────────────────────────────────────────────
stage "Gemini API key (fallback model)"
say "Gemini is the free-tier fallback (it gets wired up in Issue 10). Leave it blank to skip for now."
note "Gemini's free tier may train on your inputs, so only synthetic data is ever sent to it (ADR 0002)."
open_url "https://aistudio.google.com/apikey"
step "Click 'Create API key', pick or create a Google Cloud project, then copy the key (starts AIza)."
ask_secret GOOGLE_GENERATIVE_AI_API_KEY "Paste the Gemini key (Enter to skip):"
if [[ -n "$GOOGLE_GENERATIVE_AI_API_KEY" ]]; then
  write_env GOOGLE_GENERATIVE_AI_API_KEY "$GOOGLE_GENERATIVE_AI_API_KEY"
  set_secret GOOGLE_GENERATIVE_AI_API_KEY "$GOOGLE_GENERATIVE_AI_API_KEY"
else
  SKIPPED+=("Gemini key (re-run this wizard to add it)")
  note "Skipped."
fi
pause

# ── 4 ──────────────────────────────────────────────────────────────────────
stage "Upstash Redis (live-mode rate limits)"
say "Live mode on the shared free-tier key is limited per visitor and capped per day, so the demo stays at \$0."
say "Upstash Redis's free tier keeps those counts across Vercel's serverless instances."
note "Without it, counts live in each server instance's memory, which is fine locally but leaky in production."
if [[ -n "$(_existing UPSTASH_REDIS_REST_URL || true)" ]]; then
  note "You already have an Upstash database in $ENV_FILE. Press Enter twice to keep it."
else
  open_url "https://console.upstash.com/redis"
  step "Sign in, click 'Create Database', name it 'fixline', pick the region nearest your Vercel functions, Free plan."
  step "Open the database, scroll to 'REST API', then copy UPSTASH_REDIS_REST_URL and UPSTASH_REDIS_REST_TOKEN."
  note "Use the full token, not the read-only one: the rate limiter writes counts."
fi
ask UPSTASH_REDIS_REST_URL "Paste UPSTASH_REDIS_REST_URL (https://..., Enter to skip):" || UPSTASH_REDIS_REST_URL=""
if [[ -n "$UPSTASH_REDIS_REST_URL" ]]; then
  ask_secret UPSTASH_REDIS_REST_TOKEN "Paste UPSTASH_REDIS_REST_TOKEN:"
  [[ -n "$UPSTASH_REDIS_REST_TOKEN" ]] || { warn "The token is required with the URL."; exit 1; }
  if printf 'Authorization: Bearer %s\n' "$UPSTASH_REDIS_REST_TOKEN" |
    curl -fsS -H @- "${UPSTASH_REDIS_REST_URL%/}/ping" >/dev/null 2>&1; then
    printf '  %s✓ connected%s to Upstash\n' "$GREEN" "$RESET"
  else
    warn "Upstash didn't answer with that URL and token. Re-run the wizard and paste them again."
    exit 1
  fi
  write_env UPSTASH_REDIS_REST_URL "$UPSTASH_REDIS_REST_URL"
  write_env UPSTASH_REDIS_REST_TOKEN "$UPSTASH_REDIS_REST_TOKEN"
  note "Daily caps default to 10 live runs per visitor and 100 overall; set FIXLINE_LIVE_RUNS_PER_VISITOR"
  note "and FIXLINE_LIVE_RUNS_PER_DAY in Vercel to change them."
else
  UPSTASH_REDIS_REST_TOKEN=""
  SKIPPED+=("Upstash Redis for live-mode rate limits (re-run this wizard to add it)")
  note "Skipped."
fi
pause

# ── 5 ──────────────────────────────────────────────────────────────────────
stage "Vercel: log in and link the project"
if vercel whoami >/dev/null 2>&1; then
  note "Already logged in to Vercel as $(vercel whoami 2>/dev/null)."
else
  say "Logging in to Vercel. The CLI will open your browser to confirm."
  vercel login
fi
if [[ -f .vercel/project.json ]]; then
  note "This folder is already linked to a Vercel project (.vercel/ is git-ignored)."
else
  say "Now linking this folder to a Vercel project. The CLI asks a few questions:"
  step "'Set up and deploy?' or 'Link to existing project?': choose to set up or link."
  step "Scope: pick your personal account (Hobby plan, free)."
  step "Link to an existing project? No, unless you already made one. Project name: fixline."
  step "Code directory: ./ and accept the detected Next.js settings."
  step "If it offers to connect the GitHub repo, say yes so pushes to main auto-deploy."
  vercel link
fi
[[ -f .vercel/project.json ]] || { warn "Linking didn't complete. Re-run the wizard."; exit 1; }
pause

# ── 6 ──────────────────────────────────────────────────────────────────────
stage "Vercel: production environment variables"
say "Copying the keys into the Vercel project's Production environment."
vercel_env() {
  local name="$1" value="$2"
  vercel env rm "$name" production --yes >/dev/null 2>&1 || true
  if printf '%s' "$value" | vercel env add "$name" production >/dev/null 2>&1; then
    printf '  %s✓ set%s Vercel env %s (production)\n' "$GREEN" "$RESET" "$name"
  else
    SKIPPED+=("Vercel env $name: add it under Project → Settings → Environment Variables")
    warn "couldn't set Vercel env $name"
  fi
}
vercel_env GROQ_API_KEY "$GROQ_API_KEY"
[[ -n "$GOOGLE_GENERATIVE_AI_API_KEY" ]] && vercel_env GOOGLE_GENERATIVE_AI_API_KEY "$GOOGLE_GENERATIVE_AI_API_KEY"
if [[ -n "$UPSTASH_REDIS_REST_URL" ]]; then
  vercel_env UPSTASH_REDIS_REST_URL "$UPSTASH_REDIS_REST_URL"
  vercel_env UPSTASH_REDIS_REST_TOKEN "$UPSTASH_REDIS_REST_TOKEN"
fi
pause

# ── 7 ──────────────────────────────────────────────────────────────────────
stage "Deploy to production"
say "This builds the app on Vercel and puts the tracer page on a public URL."
note "Anyone with the URL can run live mode, which spends your Groq free-tier quota within the daily caps."
if confirm "Deploy to production now?"; then
  DEPLOY_URL=$(vercel deploy --prod) || { warn "Deploy failed. See the output above."; exit 1; }
  printf '  %s✓ deployed%s %s\n' "$GREEN" "$RESET" "$DEPLOY_URL"
  say ""
  say "That is the per-deployment URL. Vercel may protect it with a login."
  step "Find the public domain under the dashboard's Project → Domains, or run: npx vercel inspect $DEPLOY_URL"
  warn "Don't assume <project>.vercel.app: if that name is taken, Vercel adds a suffix (e.g. fixline-phi.vercel.app)."
  note "Pick the alias without your team slug in it. That one is public; the team-slug alias asks for a Vercel login."
  ask PROD_URL "Paste the public production URL:"
else
  SKIPPED+=("Production deploy: run 'npx vercel deploy --prod'")
  PROD_URL=""
fi

# ── 8 ──────────────────────────────────────────────────────────────────────
stage "Smoke test the live page"
if [[ -n "$PROD_URL" ]]; then
  open_url "$PROD_URL"
  step "Check the page loads without a Vercel login (open it in a private window to be sure)."
  step "Press 'Run Intake' and wait for a Work Order to appear."
  if confirm "Did a Work Order appear?"; then
    printf '  %s✓ live%s %s\n' "$GREEN" "$RESET" "$PROD_URL"
  else
    SKIPPED+=("Smoke test failed: check Vercel → Project → Logs, and that GROQ_API_KEY is set for Production")
  fi
else
  note "No deploy, so there's nothing to test."
fi
pause

# ── 9-10 ───────────────────────────────────────────────────────────────────
if confirm "Set up the Trello integration now? (optional, for running Fixline against a real Board)"; then
  trello_stages
else
  SKIPPED+=("Trello: run 'scripts/setup.sh trello' when you want the real Board")
fi

finish
[[ -n "$PROD_URL" ]] && say "Live URL: ${BOLD}${PROD_URL}${RESET}  (paste this back to Claude for the README)"
printf '\n'
}

run_wizard "$@"; exit
